window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-05726115b54de5c9"]={"versions": [{"id": "FIG-05726115b54de5c9", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm zur Veranschaulichung des Betriebsverhaltens einer implizit synchronisierten Schedule Table im AUTOSAR-Betriebssystem (AUTOSAR OS, Classic Platform). Das Diagramm stellt das Verhältnis zwischen einer periodisch ablaufenden Schedule Table mit definierten Expiry Points und einem zugrundeliegenden OS Counter über der Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponenten und Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>OS Counter</strong>: Frei laufender Zähler des Betriebssystems mit periodischen Ticks (Wertebereich 0 bis 9 im dargestellten Ausschnitt).\n</li><li><strong>Schedule Table (Tbl)</strong>: Periodische Tabelle der Länge 10 Ticks (Offset 0 bis 9), dargestellt in aufeinanderfolgenden Iterationen.\n</li><li><strong>Expiry Points</strong>:\n<ul class=\"fig-list\"><li><code>EP1</code> an Offset 2\n</li><li><code>EP2</code> an Offset 5\n</li><li><code>EP3</code> an Offset 8\n</li></ul>\n</li><li><strong>Zustandsachse der Schedule Table</strong>: Zeigt den Übergang von Zustand <code>STOPPED</code> in den Zustand <code>RUNNING_AND_SYNCHRONOUS</code>.\n</li><li><strong>Systemaufruf/API</strong>: Aufruf <code>StartScheduleTableAbs(Tbl, 0);</code> mit dem Parameterwert 0 als Startwert relativ zum OS Counter.\n</li><li><strong>Berechnungsformel/Notiz</strong>: <code>Process Initial Expiry Point when the Counter = 0 + Initial Offset = 2</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung und Start</strong>: Vor dem Start befindet sich die Schedule Table im Zustand <code>STOPPED</code>. Am OS-Counter-Stand 7 wird der Aufruf <code>StartScheduleTableAbs(Tbl, 0)</code> abgesetzt.\n</li><li><strong>Zustandsübergang</strong>: Mit Erreichen des im API-Aufruf spezifizierten absoluten Zählerwerts (Counter = 0) wechselt die Schedule Table unmittelbar in den Zustand <code>RUNNING_AND_SYNCHRONOUS</code> und startet ihren Zyklus synchron bei Offset 0.\n</li><li><strong>Ablauf der Expiry Points</strong>:\n<ul class=\"fig-list\"><li>Erste Iteration: <code>EP1</code> wird bei Counter = 2 (entspricht Offset 2), <code>EP2</code> bei Counter = 5 (Offset 5) und <code>EP3</code> bei Counter = 8 (Offset 8) abgearbeitet.\n</li><li>Zweite Iteration: Nach Erreichen von Offset 9 setzt die Tabelle bei Counter = 0 wieder mit Offset 0 auf und führt erneut <code>EP1</code> (Counter = 2), <code>EP2</code> (Counter = 5) sowie <code>EP3</code> (Counter = 8) aus.\n</li><li>Nachfolgende Iteration: Die Tabelle läuft weiter periodisch synchron zum OS Counter.\n</li></ul>\n</li><li><strong>Implizite Synchronisation</strong>: Da die Länge der Schedule Table (10 Ticks) exakt dem Modulo-Umlauf des OS Counters entspricht (0 bis 9) und die Tabelle synchron zum Zähler gestartet wurde, bleibt sie ohne explizite Nachsynchronisation dauerhaft im Zustand <code>RUNNING_AND_SYNCHRONOUS</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für Entwickler und Konfiguratoren zeigt das Diagramm das semantische Verhalten von <code>StartScheduleTableAbs</code>: Der Parameter bestimmt den absoluten Zählerwert, bei dem die Tabelle bei Tick 0 startet.\n</li><li>Bei impliziter Synchronisation muss die Tabellendauer dem Zählerzyklus (oder einem ganzzahligen Teiler/Vielfachen des Counters) entsprechen, damit die Schedule Table ohne Drift synchron (<code>RUNNING_AND_SYNCHRONOUS</code>) verbleibt.\n</li><li>Aktionen an den Expiry Points (z. B. Task-Aktivierungen oder Event-Setzungen) erfolgen deterministisch genau an den vordefinierten Zählerständen (<code>Counter = Startwert + Offset</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-13864b1589aeab28", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm zur Veranschaulichung des Betriebsverhaltens einer implizit synchronisierten Schedule Table im AUTOSAR-Betriebssystem (AUTOSAR OS, Classic Platform). Das Diagramm stellt das Verhältnis zwischen einer periodisch ablaufenden Schedule Table mit definierten Expiry Points und einem zugrundeliegenden OS Counter über der Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponenten und Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>OS Counter</strong>: Frei laufender Zähler des Betriebssystems mit periodischen Ticks (Wertebereich 0 bis 9 im dargestellten Ausschnitt).\n</li><li><strong>Schedule Table (Tbl)</strong>: Periodische Tabelle der Länge 10 Ticks (Offset 0 bis 9), dargestellt in aufeinanderfolgenden Iterationen.\n</li><li><strong>Expiry Points</strong>:\n<ul class=\"fig-list\"><li><code>EP1</code> an Offset 2\n</li><li><code>EP2</code> an Offset 5\n</li><li><code>EP3</code> an Offset 8\n</li></ul>\n</li><li><strong>Zustandsachse der Schedule Table</strong>: Zeigt den Übergang von Zustand <code>STOPPED</code> in den Zustand <code>RUNNING_AND_SYNCHRONOUS</code>.\n</li><li><strong>Systemaufruf/API</strong>: Aufruf <code>StartScheduleTableAbs(Tbl, 0);</code> mit dem Parameterwert 0 als Startwert relativ zum OS Counter.\n</li><li><strong>Berechnungsformel/Notiz</strong>: <code>Process Initial Expiry Point when the Counter = 0 + Initial Offset = 2</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung und Start</strong>: Vor dem Start befindet sich die Schedule Table im Zustand <code>STOPPED</code>. Am OS-Counter-Stand 7 wird der Aufruf <code>StartScheduleTableAbs(Tbl, 0)</code> abgesetzt.\n</li><li><strong>Zustandsübergang</strong>: Mit Erreichen des im API-Aufruf spezifizierten absoluten Zählerwerts (Counter = 0) wechselt die Schedule Table unmittelbar in den Zustand <code>RUNNING_AND_SYNCHRONOUS</code> und startet ihren Zyklus synchron bei Offset 0.\n</li><li><strong>Ablauf der Expiry Points</strong>:\n<ul class=\"fig-list\"><li>Erste Iteration: <code>EP1</code> wird bei Counter = 2 (entspricht Offset 2), <code>EP2</code> bei Counter = 5 (Offset 5) und <code>EP3</code> bei Counter = 8 (Offset 8) abgearbeitet.\n</li><li>Zweite Iteration: Nach Erreichen von Offset 9 setzt die Tabelle bei Counter = 0 wieder mit Offset 0 auf und führt erneut <code>EP1</code> (Counter = 2), <code>EP2</code> (Counter = 5) sowie <code>EP3</code> (Counter = 8) aus.\n</li><li>Nachfolgende Iteration: Die Tabelle läuft weiter periodisch synchron zum OS Counter.\n</li></ul>\n</li><li><strong>Implizite Synchronisation</strong>: Da die Länge der Schedule Table (10 Ticks) exakt dem Modulo-Umlauf des OS Counters entspricht (0 bis 9) und die Tabelle synchron zum Zähler gestartet wurde, bleibt sie ohne explizite Nachsynchronisation dauerhaft im Zustand <code>RUNNING_AND_SYNCHRONOUS</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für Entwickler und Konfiguratoren zeigt das Diagramm das semantische Verhalten von <code>StartScheduleTableAbs</code>: Der Parameter bestimmt den absoluten Zählerwert, bei dem die Tabelle bei Tick 0 startet.\n</li><li>Bei impliziter Synchronisation muss die Tabellendauer dem Zählerzyklus (oder einem ganzzahligen Teiler/Vielfachen des Counters) entsprechen, damit die Schedule Table ohne Drift synchron (<code>RUNNING_AND_SYNCHRONOUS</code>) verbleibt.\n</li><li>Aktionen an den Expiry Points (z. B. Task-Aktivierungen oder Event-Setzungen) erfolgen deterministisch genau an den vordefinierten Zählerständen (<code>Counter = Startwert + Offset</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-05726115b54de5c9", "to": "FIG-13864b1589aeab28", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
